$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$dataDir = Join-Path $root "data"
$outFile = Join-Path $root "bao-cao-mo-hinh-csdl.html"
$meta = Get-Content (Join-Path $root "tables-meta.json") -Raw -Encoding UTF8 | ConvertFrom-Json

function Escape-Html([string]$s) {
    if ($null -eq $s) { return "" }
    return [System.Net.WebUtility]::HtmlEncode($s)
}

function Parse-CsvTable([string]$path) {
    $lines = Get-Content $path -Encoding UTF8
    $rows = @()
    foreach ($line in $lines) {
        $m = [regex]::Matches($line, '"([^"]*)"')
        $vals = @()
        foreach ($x in $m) { $vals += $x.Groups[1].Value }
        if ($vals.Count -ge 1) { $rows += ,$vals }
    }
    if ($rows.Count -lt 1) { return $null }
    $first = $rows[0][0]
    if ($first -match 'T[\u00ean]n b[\u1ea3]ng\s*:\s*(\S+)') { $tableName = $matches[1] }
    elseif ($first -match 'Tên bảng\s*:\s*(\S+)') { $tableName = $matches[1] }
    else { $tableName = [System.IO.Path]::GetFileNameWithoutExtension($path) }
    $columns = @()
    if ($first -match 'T[\u00ean]n c[\u1ed9]t\s+(.+)$') {
        $columns += [pscustomobject]@{ Name = $matches[1].Trim(); Type = $rows[0][1]; Length = $rows[0][2]; Desc = $rows[0][3] }
    }
    elseif ($first -match 'Tên cột\s+(.+)$') {
        $columns += [pscustomobject]@{ Name = $matches[1].Trim(); Type = $rows[0][1]; Length = $rows[0][2]; Desc = $rows[0][3] }
    }
    for ($i = 1; $i -lt $rows.Count; $i++) {
        $r = $rows[$i]
        if ($r[0].Trim() -eq "") { continue }
        $columns += [pscustomobject]@{ Name = $r[0]; Type = $r[1]; Length = $r[2]; Desc = $r[3] }
    }
    return [pscustomobject]@{ Table = $tableName; Columns = $columns }
}

$tables = @()
foreach ($sheet in $meta.order) {
    $path = Join-Path $dataDir ($sheet + ".csv")
    if (-not (Test-Path $path)) { Write-Warning "Missing $path"; continue }
    $parsed = Parse-CsvTable $path
    $desc = $meta.descriptions.$parsed.Table
    $group = $meta.groups.$sheet
    $tables += [pscustomobject]@{
        Sheet = $sheet
        Table = $parsed.Table
        Group = $group
        Description = $desc
        Columns = $parsed.Columns
    }
}

$colCount = ($tables | ForEach-Object { $_.Columns.Count } | Measure-Object -Sum).Sum
$mid = New-Object System.Text.StringBuilder

function W([string]$line) { [void]$mid.AppendLine($line) }

W '<div class="summary-box">'
W ("<div class=""summary-item""><div class=""num"">{0}</div><div class=""lbl"">B&#7843;ng d&#7919; li&#7879;u</div></div>" -f $tables.Count)
W ("<div class=""summary-item""><div class=""num"">{0}</div><div class=""lbl"">C&#7897;t d&#7919; li&#7879;u</div></div>" -f $colCount)
W '<div class="summary-item"><div class="num">4</div><div class="lbl">Nh&#243;m nghi&#7879;p v&#7909;</div></div>'
W '</div>'

W '<h3>1.1. M&#7909;c &#273;&#237;ch</h3><ul>'
W '<li>Qu&#7843;n l&#253; danh m&#7909;c &#273;&#224;o t&#7841;o: b&#7853;c, ng&#224;nh, chuy&#234;n ng&#224;nh, kh&#243;a, l&#7899;p.</li>'
W '<li>Qu&#7843;n l&#253; t&#224;i nguy&#234;n gi&#7843;ng d&#7841;y: m&#244;n h&#7885;c, gi&#225;o vi&#234;n, ph&#242;ng h&#7885;c, ca h&#7885;c.</li>'
W '<li>Ph&#226;n c&#244;ng m&#244;n h&#7885;c theo l&#7899;p v&#224; x&#7871;p th&#7901;i kh&#243;a bi&#7875;u.</li>'
W '<li>Theo d&#245;i ti&#7871;n &#273;&#7897; gi&#7843;ng d&#7841;y, tr&#7841;ng th&#225;i c&#244;ng khai TKB theo ni&#234;n h&#7885;c.</li>'
W '</ul>'

W '<h3>1.2. C&#244;ng ngh&#7879;</h3>'
W '<table><thead><tr><th>H&#7841;ng m&#7909;c</th><th>Gi&#225; tr&#7883;</th></tr></thead><tbody>'
W '<tr><td>H&#7879; qu&#7843;n tr&#7883; CSDL</td><td>Microsoft SQL Server</td></tr>'
W '<tr><td>Truy c&#7853;p d&#7919; li&#7879;u</td><td>ADO.NET (SqlConnection, SqlCommand, SqlDataAdapter)</td></tr>'
W '<tr><td>Ki&#7871;n tr&#250;c</td><td>3 l&#7899;p: WebForms/WinForms &#8211; BLL &#8211; DAL</td></tr>'
W '<tr><td>Quy &#432;&#7899;c b&#7843;ng</td><td>Ti&#7873;n t&#7889; SIM_, PascalCase</td></tr>'
W '</tbody></table></section>'

W '<section id="sec3"><h2>3. DANH M&#7908;C B&#7842;NG D&#7918; LI&#7878;U</h2>'
W '<table><thead><tr><th>STT</th><th>T&#234;n b&#7843;ng</th><th>T&#234;n ti&#7871;ng Vi&#7879;t</th><th>Nh&#243;m</th><th>S&#7889; c&#7897;t</th></tr></thead><tbody>'
$stt = 1
foreach ($t in $tables) {
    W ("<tr><td style=""text-align:center"">{0}</td><td><span class=""badge"">{1}</span></td><td>{2}</td><td>{3}</td><td style=""text-align:center"">{4}</td></tr>" -f $stt, (Escape-Html $t.Table), (Escape-Html $t.Sheet), (Escape-Html $t.Group), $t.Columns.Count)
    $stt++
}
W '</tbody></table></section>'

W '<section id="sec4"><h2>4. CHI TI&#7870;T T&#7910;NG B&#7842;NG</h2>'
$currentGroup = ""
foreach ($t in $tables) {
    if ($t.Group -ne $currentGroup) {
        $currentGroup = $t.Group
        W ("<h3>{0}</h3>" -f (Escape-Html $currentGroup))
    }
    $tblId = ($t.Table -replace '[^a-zA-Z0-9]', '-').ToLower()
    W ("<div class=""table-block"" id=""tbl-{0}"">" -f $tblId)
    W ("<h3>{0} &#8211; <span class=""badge"">{1}</span></h3>" -f (Escape-Html $t.Sheet), (Escape-Html $t.Table))
    if ($t.Description) { W ("<p>{0}</p>" -f (Escape-Html $t.Description)) }
    W '<table><thead><tr><th>STT</th><th>T&#234;n c&#7897;t</th><th>Ki&#7875;u d&#7919; li&#7879;u</th><th>&#272;&#7897; d&#224;i</th><th>M&#244; t&#7843;</th></tr></thead><tbody>'
    $i = 1
    foreach ($c in $t.Columns) {
        $descText = if ($c.Desc -and $c.Desc -ne "NULL") { Escape-Html $c.Desc } else { "" }
        W ("<tr><td style=""text-align:center"">{0}</td><td><strong>{1}</strong></td><td>{2}</td><td style=""text-align:center"">{3}</td><td>{4}</td></tr>" -f $i, (Escape-Html $c.Name), (Escape-Html $c.Type), (Escape-Html $c.Length), $descText)
        $i++
    }
    W '</tbody></table></div>'
}
W '</section>'

$head = Get-Content (Join-Path $root "report-template-head.html") -Raw -Encoding UTF8
$tail = Get-Content (Join-Path $root "report-template-tail.html") -Raw -Encoding UTF8
$html = $head + $mid.ToString() + $tail
[System.IO.File]::WriteAllText($outFile, $html, [System.Text.UTF8Encoding]::new($false))
Write-Host "OK: $outFile"
Write-Host "Tables: $($tables.Count), Columns: $colCount"

