function Normalize-CellPrefix([string]$value, [string[]]$prefixes) {
    if ($null -eq $value) { return "" }
    $v = $value.Trim()
    foreach ($prefix in $prefixes) {
        if ($v.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            $v = $v.Substring($prefix.Length).Trim()
            break
        }
    }
    if ($v -eq "NULL") { return "" }
    return $v
}

function Format-DataType([string]$type, [string]$length) {
    $t = Normalize-CellPrefix $type @("Kiểu dữ liệu ", "Kieu du lieu ")
    $l = Normalize-CellPrefix $length @("Độ dài ", "Do dai ")
    if ($t -eq "") { return "" }

    $tLower = $t.ToLower()
    $withLength = @("nvarchar", "varchar", "char", "nchar", "varbinary", "binary")

    foreach ($base in $withLength) {
        if ($tLower -eq $base) {
            if ($l -ne "" -and $l -match '^\d+$') {
                return ($base + "(" + $l + ")")
            }
            return $base
        }
    }

    if ($tLower -eq "decimal" -or $tLower -eq "numeric") {
        if ($l -ne "") {
            return ($t + "(" + $l + ")")
        }
    }

    return $t
}

