function Split-FirstRowColumns([string]$nameCell, [string]$typeCell, [string]$lengthCell, [string]$descCell) {
    $nameCell = $nameCell.Trim()
    if ($nameCell -match 'T[\u00ea\u1ebf\u1ec3]n c[\u1ed9\u1ed1]t\s+(.+)$') {
        $nameCell = $matches[1].Trim()
    }
    elseif ($nameCell -match 'Tên cột\s+(.+)$') {
        $nameCell = $matches[1].Trim()
    }

    $typesRaw = Strip-ExportLabel $typeCell '^\s*(?:Ki.+?u d.+? li.+?u)\s+(.+)$'
