        $descs = $descsRaw -split '\s+(?=NULL\b|[\p{L}])', 0
        if ($descs.Count -lt $names.Count) {
            $descs = $descsRaw -split '(?<=\bNULL\b)\s+'
        }
    }
    else {
        $descs = @($descsRaw)
    }

    $result = @()
    for ($i = 0; $i -lt $names.Count; $i++) {
        $n = $names[$i]
        $tp = if ($i -lt $types.Count) { $types[$i] } else { "" }
        $ln = if ($i -lt $lengths.Count) { $lengths[$i] } else { "" }
        $ds = if ($i -lt $descs.Count) { $descs[$i] } else { "" }
        if ($ds -eq "NULL") { $ds = "" }
        $result += [pscustomobject]@{ Name = $n; Type = $tp; Length = $ln; Desc = $ds }
    }
    return $result
}

